ProjectALife.DialogueShards["scenes_any_28"] = {
{"s7_c02_after_the_army_049","any",3,"reg=raider|tmp=predator,seasoned|day=10,200|mood=fear|world=vehicle",{1,"When the Army comes in and cleans this county up, what do we say?",2,"We say we were a church group",3,"With a truck full of other people's wedding rings",2,"A church group that does a lot of weddings",1,"I'm serious, somebody's gonna point at us"}},
{"s7_c02_dale_laughed_050","any",2,"reg=raider|tmp=predator|mood=funny|world=vehicle,water",{1,"Dale laughed today",2,"At what?",1,"Petey fell off the tailgate into the creek - Dale laughed so hard he had to sit down",2,"Good, everybody go ask him for stuff - right now, quick, while it lasts"}},
{"s7_c02_objector_mutter_051","any",1,"reg=raider|tmp=seasoned,predator|hour=22,4|mood=grim|world=fence",{1,"Mama used to say you're known by the company you keep",1,"Well, company I keep ties folks to fences",1,"So I guess I'm known now, nobody left to know me, but I'm known"}},
{"s7_c02_shot_near_the_kid_052","any",3,"reg=raider|tmp=predator,seasoned|mood=angry",{1,"You fired over a kid's head to make the mama move faster",2,"Over - not at, three feet over",1,"With that rifle? You can't hit three feet over a Coke can",3,"She moved faster, though",1,"Next time you do that I'm standing between you and the kid - try three feet over me"}},
{"s7_c03_clothesline_jeans_001","any",3,"reg=prison|day=1,30|mood=funny",{1,"These jeans came off a clothesline in Rosewood, they're a woman's jeans",2,"They fit you",1,"That's the part that bothers me",3,"Beats khakis with the state letters running down the leg"}},
{"s7_c03_softball_cap_002","any",3,"reg=prison|day=3,40|mood=funny",{1,"Everybody in Kentucky knows a state haircut when they see one",2,"So grow it out",1,"In three weeks? I look like a peach",3,"Wear a ball cap, every man in this state wears a ball cap",1,"Only cap I got says Corrections Softball League across the front"}},
{"s7_c03_nineteen_days_003","any",3,"reg=prison|mood=grim|world=door",{1,"I had nineteen days left - nineteen",2,"So why'd you run?",1,"Door was open and every man on the tier was running - you ever stand still while everybody runs?",3,"So now you're an escapee with nineteen days left",1,"Now I'm an escapee with forever left, thanks for the arithmetic"}},
{"s7_c03_blankenship_keys_004","any",3,"reg=prison|mood=sad|world=building",{1,"Officer Blankenship opened C-block himself, walked the whole run with his key ring",2,"Why'd he do that?",1,"Said he wasn't gonna be the man who left a hundred men locked in with that",3,"Where's Blankenship at now?",1,"Last I saw, holding the sally port gate for the kitchen crew - then the sally port was full"}},
{"s7_c03_arm_around_plate_005","any",3,"reg=prison|mood=warm",{1,"Quit guarding your plate like that, nobody wants your beans",2,"Arm just goes there",1,"It's a paper plate in a cornfield, Luther",2,"Arm still goes there",3,"Eleven years, his arm goes there - let the man eat"}},
{"s7_c03_reno_says_006","any",2,"reg=prison|tmp=predator|mood=fear",{1,"Reno says you're the one told Captain Hale about the shank in B-dorm - back in ninety-one",2,"Reno says a lot of things",1,"Reno's got the only shotgun",2,"Then I guess I'm a light sleeper from now on"}},
{"s7_c03_khakis_no_questions_007","any",3,"reg=prison|day=2,60|hour=16,5|mood=fear",{1,"Army catches you in state khakis, that's it, no questions asked",2,"Army catches you in anything, that's it",1,"Yeah, but in khakis they don't feel bad about it after",3,"Burn 'em - tonight, I don't care if you got nothing else to wear"}},
{"s7_c03_spotlight_list_008","any",3,"reg=prison|hour=20,5|mood=fear",{1,"Helicopter came over twice last night - low - light on",2,"Looking for us",3,"Looking for anybody, we ain't that special, Tito",2,"We're fourteen men that walked out of a prison, that's special enough for a list"}},
{"s7_c03_book_of_stamps_009","any",3,"reg=prison|mood=funny",{1,"Got a whole book of stamps off the post office counter - twenty-nine centers",2,"Stamps - out here",1,"Inside, a book of stamps got you two honey buns and a haircut",3,"Out here it gets you mail to nowhere",1,"Still feel rich carrying 'em - leave me alone"}},
{"s7_c03_honk_twice_po_010","any",3,"reg=prison|day=2,30|mood=funny",{1,"Supposed to check in with my parole officer Monday",2,"You gonna?",1,"Thinking I'll drive by her office - honk twice - get it on the record",3,"She's probably one of them by now",1,"Then she can chase me for a real reason, finally"}},
{"s7_c03_cut_hay_lifer_011","any",3,"reg=prison|hour=6,20|mood=warm|world=building",{1,"Old Tolliver's doing life - Happiest man in this barn",2,"Why wouldn't he be? Life sentence got real short for everybody",3,"He says it's the first July he's smelled cut hay since nineteen seventy-four",1,"He's out there in the field right now, just standing in it"}},
{"s7_c03_dont_say_boss_012","any",3,"reg=prison|tmp=predator|mood=fear",{1,"Reno's mad",2,"What'd we do now?",1,"The new fish called him boss, he hates boss - boss is what the COs called each other",3,"So what's he want to be called?",1,"Reno - just Reno, and quit watching him eat"}},
{"s7_c03_christmas_letter_013","any",3,"reg=prison|mood=sad",{1,"Last I heard, my wife was in Irvington. Used to be fifteen miles from home",2,"Your ex-wife",1,"She still wrote me at Christmas",3,"She wrote you so you'd sign the papers",1,"Still wrote",2,"We're not planning a drive just because you still have an old address"}},
{"s7_c03_sheriffs_office_knock_014","any",3,"reg=prison|tmp=predator|mood=grim|world=door",{1,"Door opens faster if you holler Sheriff's office",2,"Say it right, though, don't say it like you're asking",1,"Sheriff's office! Open the door!",3,"Now you sound just like the ones that picked you up",1,"That's the idea"}},
{"s7_c03_co_shirt_015","any",3,"reg=prison|hour=16,5|mood=angry",{1,"Take that shirt off",2,"It's a good shirt - pockets - shoulder straps",1,"It's a CO shirt, every time I see it my shoulders go up around my ears",3,"Wear it on a run, sure, folks see it, they think the state's still in charge",1,"Not around me, not after dark"}},
{"s7_c03_sunday_grass_016","any",3,"reg=prison|mood=grim|world=door",{1,"Friday night the tier lights went out and nobody came for count",2,"Saturday morning nobody came with breakfast",3,"Saturday noon Big Mike took the door off its track with a bunk rail",1,"Sunday I stood on grass"}},
{"s7_c03_hospital_corners_017","any",2,"reg=prison|mood=sad",{1,"My cellie turned Saturday night - Ronald, twelve years in the same eight by ten",2,"What'd you do?",1,"What you do, then I made up his bunk - hospital corners - habit"}},
{"s7_c03_arson_fire_018","any",3,"reg=prison|mood=funny",{1,"We didn't ask inside. We don't ask out here either. What you were in for stays yours",2,"I'm asking, 'cause he sleeps next to me",3,"Arson",2,"Okay - Arson",3,"You asked",2,"Right, I asked. Well... fire's yours to look after, I suppose"}},
{"s7_c03_screen_door_buzz_019","any",3,"reg=prison|day=2,30|mood=sad|world=door,building",{1,"Watched Pee Wee stand at a screen door for a full minute - just stood there",2,"Waiting on the buzz",1,"It's just a screen door with a hole in it, nothing's even locked",3,"Took me three days to open a refrigerator without asking somebody first"}},
{"s7_c03_two_for_one_store_020","any",2,"reg=prison|tmp=predator|mood=funny",{1,"Borrow one can, pay back two, same as inside",2,"We ain't inside",1,"My store, my rules - you want the can or not?",2,"What kind of can?",1,"Store don't take questions, store takes yes",2,"Gimme the can"}},
{"s7_c03_judges_house_021","any",3,"reg=prison|tmp=predator|day=4,200|mood=funny",{1,"Brick house up the hill in Rosewood, that's Judge Ashcraft's",2,"The one that gave you fifteen?",1,"Twelve, four suspended, he was fair, honestly",3,"So we skip it?",1,"No, we hit it, I just ain't gonna be rude about it"}},
{"s7_c03_army_paper_022","any",3,"reg=prison|day=3,200|mood=fear",{1,"Army takes your fingerprints at the checkpoint, heard it on the scanner",2,"Army's computers are down same as everything",3,"Army's got paper - Army always has paper, carbon copies of paper",1,"Then we go around, we go around every checkpoint in Kentucky"}},
{"s7_c03_maddox_truck_023","any",3,"reg=prison|day=5,200|mood=fear",{1,"Sergeant Maddox is alive, saw his truck at the Muldraugh feed store",2,"Maddox, with the stick",1,"He had a rifle today",3,"He's looking for us?",1,"He's looking for Donnie, everybody knows what Donnie did to Maddox's partner in the laundry",2,"So we give him Donnie"}},
{"s7_c03_mutter_two_steps_024","any",1,"reg=prison|mood=calm|world=door",{1,"Eight steps from the barn door to the hay bale - the cell was six",1,"Two extra steps, that's what I got out of all this",1,"Walk 'em every night anyhow, six, seven, eight - turn around"}},
{"s7_c03_old_rule_kids_025","any",3,"reg=prison|tmp=predator|day=4,200|mood=grim",{1,"Inside, you hurt a kid, you didn't make it to chow - that rule walked out the gate with us",2,"Reno's rule or the old rule?",1,"The old rule - Reno just keeps it",3,"So if we find a house with kids in it, we leave it alone",1,"We leave it alone. And we don't pretend the next house is empty just because we want something"}},
{"s7_c03_eight_seconds_026","any",2,"reg=prison|mood=funny",{1,"You know what I miss? Commissary honey bun, in the dayroom microwave - eight seconds",2,"You miss prison food?",1,"I miss eight seconds - don't twist it around"}},
{"s7_c03_booking_photo_eye_027","any",3,"reg=prison|day=1,20|mood=funny",{1,"Lady saw us coming and said, you're the men from the Channel 11 news",2,"TV ain't been on since the weekend",1,"She saw it before, said they showed Leroy's picture",3,"Which picture?",1,"The booking one, with the eye",3,"I hate that picture"}},
{"s7_c03_walk_back_in_028","any",3,"reg=prison|day=6,200|mood=grim|world=building",{1,"Thinking about walking back",2,"Back where?",1,"Back. Walls, a gate, a kitchen. I catch myself remembering it as somewhere safe",3,"You don't know what's in there now. It's not the place we remember",1,"Then they can have the top bunk, I'll take the floor"}},
{"s7_c03_county_man_walk_029","any",2,"reg=prison|tmp=predator|mood=fear",{1,"New fella says he was in county lockup - hot checks",2,"He don't walk like a county man",1,"How's a county man walk?",2,"Like he's late for something, that one walks like he's got nowhere to be for twenty years"}},
{"s7_c03_fish_asks_again_030","any",2,"reg=prison|mood=sad",{1,"The new fish keeps asking when we're going home",2,"Tell him",1,"I told him, he asked again an hour later, like maybe I'd know by then",2,"Tell him again, then, tell him every hour - it's cheaper than a bullet"}},
{"s7_c03_blanket_no_vote_031","any",3,"reg=prison|tmp=predator|mood=grim",{1,"How long are we keeping the CO in the corn crib?",2,"Till Reno says",3,"He's eating our food",1,"He was decent, handed out extra blankets that January the boiler quit",2,"Then he gets a blanket, he don't get a vote"}},
{"s7_c03_shopping_cart_hour_032","any",2,"reg=prison|tmp=predator|day=1,30|mood=funny",{1,"First thing I robbed out here was a Kroger, no clerk, no cameras, no nothing",2,"What'd you take?",1,"A cart, pushed a shopping cart up and down the aisles for an hour - laughing like an idiot",2,"What was in the cart?",1,"Everything - pickles - a pillow, fourteen years, man, I wanted a pillow"}},
{"s7_c03_ankle_bracelet_033","any",3,"reg=prison,raider|mood=funny",{1,"Fella we stopped had one of them ankle bracelets on - house arrest",2,"Still blinking?",1,"Still blinking, and he won't step one foot past his yard line",3,"Tell him nobody's watching the box",1,"I did, he said that's exactly what they'd want you to think"}},
{"s7_c03_front_tooth_picture_034","any",3,"reg=prison|mood=sad",{1,"Got a boy in Valley Station I ain't never met - four in September",2,"Valley Station's gone, that's the Louisville side",1,"I know where it is",3,"You want to go look?",1,"Got a picture his mama sent, he's missing a front tooth in it, that's who I'd be looking for"}},
{"s7_c03_leaflet_suspicious_035","any",3,"reg=prison|day=5,200|mood=funny",{1,"Leaflet off the helicopter, report suspicious persons to the nearest checkpoint",2,"We're the suspicious persons",3,"Report us to who? We're sleeping in that checkpoint's blind spot",1,"Fold it up - Army paper burns real good"}},
{"s7_c03_seniority_pick_036","any",3,"reg=prison|tmp=predator|mood=funny",{1,"We pick loot in number order, lowest inmate number first",2,"Lowest number's been down longest - that's Tolliver",3,"Tolliver's number is from nineteen seventy-four, he picks first till the sun burns out",1,"That's seniority, want first pick, you should've started younger"}},
{"s7_c03_squirrel_gun_liar_037","any",3,"reg=prison|mood=funny",{1,"How many of us ever fired a real gun? Raise 'em",2,"Two hands, and one of 'em's lying",3,"I shot a squirrel gun when I was nine",1,"That's the one lying",3,"It was a BB gun, it had a squirrel on the box"}},
{"s7_c03_mutter_eighteen_years_038","any",1,"reg=prison|hour=22,4|mood=grim|world=road",{1,"Eighteen years for one Saturday night in a parking lot",1,"Now every night's that Saturday, everybody's got something in their hand",1,"And nobody's getting eighteen years for it"}},
{"s7_c03_visiting_sandwich_039","any",2,"reg=prison|mood=sad",{1,"My girl drove up every other Sunday, bought me a vending machine sandwich - pimento cheese",2,"Every time?",1,"Every time, I hate pimento cheese",2,"You tell her?",1,"Six years - never did, I'd eat one right now, I'll tell you that"}},
{"s7_c03_took_care_big_mike_040","any",3,"reg=prison|day=3,200|mood=grim|world=door",{1,"Who took care of Big Mike?",2,"I did, out by the silo - he asked me to",3,"He got us out that door",2,"I know what he did, I'm the one that dug",1,"We should say something, a word, anyhow",2,"Said it already, it was just his name"}},
{"s7_c03_count_the_cans_reno_041","any",3,"reg=prison|tmp=predator|hour=4,11|mood=angry|world=vehicle",{1,"Reno counted the canned stuff this morning - three times - out loud",2,"And?",1,"And he's short two, and he's sitting on the tailgate sharpening a screwdriver",3,"It was me, I'll tell him",1,"Don't tell him, put two back where he'll find 'em and look surprised"}},
{"s7_c03_cant_read_the_mail_042","any",2,"reg=prison|mood=warm",{1,"Read me my mama's letter again, the one about the garden",2,"You got it memorized, Junebug",1,"I like how you do the part about the tomatoes splitting",2,"Alright, one more time - then you're learning to read, starting tomorrow"}},
{"s7_c03_dog_handler_k9_043","any",3,"reg=prison|day=2,40|mood=fear|world=water",{1,"You hear that baying? That's the prison hounds",2,"Loose? Without the handler?",1,"Handler's gone, nobody fed 'em, they're tracking whatever smells like inmate",3,"We all smell like inmate",1,"Then roll in the creek, all of you - right now"}},
{"s7_c03_parking_lot_first_beer_044","any",2,"reg=prison|day=1,20|mood=funny",{1,"First beer in nine years and I puked it on the pumps",2,"Body forgot how",1,"Body forgot - I didn't, I drank the second one real slow, out of spite"}},
{"s7_c03_the_house_with_bars_045","any",3,"reg=prison|tmp=predator|day=5,200|mood=funny|world=building",{1,"Family in {town} put bars on all their windows, welded 'em on",2,"So they locked themselves in",1,"Put themselves on lockdown - Voluntary",3,"Give it a month, walls quit feeling safe after about a month",1,"Nah, after a month they feel like a sentence"}},
{"s7_c03_tolliver_on_the_army_046","any",3,"reg=prison|day=8,200|mood=calm",{1,"Tolliver says don't worry about the Army, worry about the Army leaving",2,"What's that mean?",1,"Says while they're here there's a wall, once they're gone, it's just us and every crew in the county",3,"Tolliver's been locked up since before I was born - what's he know?",1,"He knows what a yard looks like when the guards walk off"}},
{"s7_c03_knuckle_ink_047","any",2,"reg=prison|mood=grim",{1,"Man took one look at the ink on my knuckles and handed me his wallet",2,"Saved you a speech",1,"I was gonna ask him for directions"}},
{"s7_c03_big_yard_open_048","any",3,"reg=prison|day=1,15|hour=19,23|mood=fear",{1,"Too much sky out here, I keep looking for the towers",2,"There's no towers",1,"That's what I'm saying, nobody's watching the yard - anybody can come across it",3,"Anything can",1,"Don't help, Dukes"}},
{"s7_c03_split_with_the_dead_049","any",3,"reg=prison|tmp=predator|hour=16,5|mood=grim",{1,"We was sixteen when we left, split the first haul sixteen ways",2,"How many ways tonight?",1,"Nine",3,"So the shares are bigger",1,"Yeah, Dukes, the shares are bigger - be happy"}},
{"s7_c03_mama_on_the_porch_050","any",3,"reg=prison|tmp=predator|day=3,60|mood=sad|world=vehicle,building",{1,"We drove by my mama's place in Ekron, she was on the porch",2,"You stop?",1,"No - Reno said no stops",3,"She see you?",1,"She waved at the truck, like she waves at every truck"}},
{"s7_c03_court_date_friday_051","any",2,"reg=prison,raider|day=2,20|mood=funny",{1,"I had a court date Friday for the appeal, took my lawyer four years to get it",2,"Think you'd have won?",1,"Doesn't matter now, I'm counting it as a win, no-show on their side"}},
{"s7_c03_chaplain_gone_052","any",3,"reg=prison|mood=sad|world=door",{1,"Chaplain Reese stayed in the chapel Saturday, wouldn't come out",2,"He could've walked with us",1,"Said somebody ought to be in there if any of the men wanted to talk",3,"Anybody go talk to him?",1,"I did, for about a minute - then the door by the gym went and he told me run"}},
{"s7_c04_rotor_kill_fire_001","any",3,"reg=raider,prison|hour=20,4|mood=fear",{1,"Rotors, kill the fire - kill it!",2,"Piss on it - it's faster",3,"I ain't pissing on supper",1,"Supper or a spotlight - pick one quick"}},
{"s7_c04_burn_the_field_002","any",3,"reg=raider|day=5,200|mood=fear",{1,"Heard the Army's gonna burn the whole county off, like a farmer burns a field",2,"Who told you that?",1,"Fella we stopped at the Ekron crossroads",3,"A man getting robbed will say anything to scare you off",1,"He said it after we were done robbing him, that's what bothers me"}},
{"s7_c04_masks_in_a_line_003","any",3,"reg=raider,prison|day=3,200|mood=fear",{1,"Saw a squad on 31W in them rubber masks, walking in a line like ducks",2,"Masks means they think it's in the air",3,"Masks means they don't want nobody remembering their faces after",1,"Either way I held my breath till they passed, whole minute and a half"}},
{"s7_c04_no_patches_004","any",3,"reg=raider,prison|day=6,200|hour=16,5|mood=fear",{1,"The ones at the rail yard had no patches, no name tapes - nothing on 'em",2,"Guard?",3,"Guard's got patches all over, guard's got their mama's name sewed on",1,"These didn't talk - hand signals - put down six of them things and never quit walking",2,"We're moving camp - tonight"}},
{"s7_c04_buck_was_driving_005","any",3,"reg=raider|day=4,200|mood=grim|world=vehicle,door",{1,"They didn't holler stop, didn't use the loudspeaker, just opened up on the truck",2,"Buck was driving",1,"Buck was driving",3,"We getting the truck back?",1,"Truck's sitting in the middle of the bridge with the door open - go get it, Squirrel"}},
{"s7_c04_walk_up_hands_high_006","any",3,"reg=raider|day=8,200|mood=fear|world=vehicle",{1,"What if we walk up to the Army with our hands up? Say we're just survivors",2,"With what's in that truck bed?",1,"We leave the truck",3,"You got Mrs. Collier's rings on three fingers",1,"I can take rings off",3,"Take off your face, then, half of {town} has seen it through a windshield"}},
{"s7_c04_count_the_guns_007","any",2,"reg=raider|tmp=predator|hour=21,3|mood=fear",{1,"Count 'em, rifles, pistols, shotguns - who's holding what",2,"Why?",1,"'Cause whoever's holding the most is boss by Friday, whether Dale's heard about it or not",2,"And who's holding the most?",1,"Don't know, that's why I'm counting"}},
{"s7_c04_shopping_basket_marker_008","any",3,"reg=raider|day=10,200|mood=sad",{1,"Wendell's under the gravel behind the Dollar General",2,"Anybody mark it?",1,"Put a shopping basket upside down on it, the red kind",3,"Well, that's something, anyway"}},
{"s7_c04_filed_numbers_009","any",3,"reg=raider|day=7,200|mood=grim",{1,"Deserter wants in, brought two cases of rations and a rifle with the numbers filed off",2,"Filed off means he's smarter than us",3,"Means the Army's hunting that rifle - and him, and now us",1,"The rations are real good, though",3,"Everything's real good right up to the helicopter"}},
{"s7_c04_before_the_sweep_010","any",3,"reg=raider|tmp=predator|day=7,200|mood=calm|world=cars",{1,"If the Army sweeps {town} next week, everything in them houses goes to the Army",2,"So we go first",1,"We go first, and fast, four houses a day - the family houses last",3,"Why last?",1,"I'm guessing the Army would take families out. I don't know that, or whether any house would be empty"}},
{"s7_c04_bathroom_scale_011","any",3,"reg=raider,prison|mood=funny|world=building",{1,"Bathroom scale split, every pile weighs the same",2,"My pile's all charcoal, it's heavy and it's worthless",3,"Mine's two pistols - weighs nothing - worth everything",1,"Scale don't care - scale's fair",2,"Scale's stupid"}},
{"s7_c04_rhonda_has_the_keys_012","any",3,"reg=raider|day=20,200|mood=grim",{1,"Since the boss got bit, it's Rhonda's crew",2,"Nobody voted",3,"Rhonda had the key to the ammo box on her neck when he went - that was the vote",1,"She's better at it than he was - honestly",2,"Don't let her hear you say honestly"}},
{"s7_c04_travis_walked_off_013","any",3,"reg=raider|tmp=predator,seasoned|day=10,200|hour=4,11|mood=sad",{1,"Travis walked off this morning, right down the center line with his bag",2,"And nobody shot him?",1,"Vernon raised up, then he put it back down",3,"Why?",1,"Said he wanted to see if a man could just walk off - said he'd like to know that for himself"}},
{"s7_c04_cons_at_truck_stop_014","any",3,"reg=raider|day=5,200|mood=fear|world=vehicle",{1,"Escaped cons took the truck stop, twelve of 'em, maybe more",2,"They won't last, cons can't shoot",3,"Cons don't need to shoot, they're used to living on nothing and waiting",1,"Waiting's the worst thing a person can be good at right now"}},
{"s7_c04_raiders_amateurs_015","any",3,"reg=prison|day=6,200|mood=angry|world=building",{1,"That crew with the orange paint is shooting at every mailbox from here to Riverside",2,"Amateurs",1,"Amateurs that'll bring the Army down on every man in this county with a record",3,"That's every man in this county",1,"Every man in this barn, anyhow"}},
{"s7_c04_farmers_next_016","any",3,"reg=raider|day=25,200|mood=grim|world=trees",{1,"Stores are picked, houses are picked - next it's farmers",2,"Farmers shoot back, and they know every tree",3,"Then we trade with farmers",1,"Trade what? We don't make nothing, we never made nothing in our lives"}},
{"s7_c04_green_house_scratch_017","any",3,"reg=raider|tmp=predator|hour=16,5|mood=fear",{1,"Old boy in the green house... ha! Grabbed his coat and he clawed the hell out of me. Look",2,"Did he look sick?",1,"Sweaty, that's all. Everybody sweats, for Christ's sake",3,"Let me see your arm",1,"Anyhow - who's got first watch tonight?"}},
{"s7_c04_just_the_canteen_018","any",3,"reg=raider|tmp=predator,seasoned|day=6,200|mood=sad",{1,"After they got his brother and cousin at a checkpoint, he wanted out of the crew",2,"Nobody left that crew with a share",1,"He asked for just the canteen. Kept saying, just the canteen, okay?",3,"I told them to let him have it. Felt like a small thing to argue over then"}},
{"s7_c04_brandenburg_says_019","any",3,"reg=raider|day=8,200|mood=calm|world=road",{1,"Brandenburg crew says the Army pulled back off the Rosewood road",2,"Brandenburg crew says a lot - Brandenburg crew wants us on the Rosewood road",3,"Why would they want that?",2,"'Cause they're working the Riverside road, and they'd like us nowhere near it"}},
{"s7_c04_crossing_guard_020","any",3,"reg=raider|tmp=predator|mood=funny",{1,"Try it again, hands up",2,"Hands up!",1,"You sound like you're asking somebody to slow dance",3,"He sounds like a crossing guard",2,"Hands UP, motherfucker!",1,"Better, now try it without your voice cracking in the middle"}},
{"s7_c04_splitting_ice_021","any",3,"reg=raider,prison|hour=11,18|mood=funny",{1,"Bag of ice out of that man's cooler - who gets it?",2,"Split it",3,"How do you split ice?",1,"While y'all figure it out, it's splitting itself",2,"Everybody put a hand on it - go on, just hold it"}},
{"s7_c04_mutter_my_old_house_022","any",1,"reg=raider|tmp=predator,seasoned|mood=sad|world=door,window,building",{1,"Kicked a door on {street} and it was my own house - from before the divorce, she kept the curtains I hated",1,"Nobody home, took the canned stuff, left the picture of the girls on the fridge",1,"Told the crew it was a bust"}},
{"s7_c04_bodies_on_sandbags_023","any",3,"reg=prison|day=6,200|mood=grim|world=building",{1,"Heard if you help the Army on the wall, they wipe your record",2,"Heard it from who?",1,"Fella on the CB, said they need bodies up on the sandbags",3,"They need bodies, alright, that's the exact word they'd pick"}},
{"s7_c04_guardsman_uniform_024","any",3,"reg=raider|tmp=predator|day=5,200|mood=grim|world=door",{1,"Took the Guardsman's uniform, pants are short, but the shirt fits",2,"What for?",1,"Families open the door for a uniform, they come out running with their bags already packed",3,"Army sees you in that, there won't be a trial - there won't be a question",1,"Then I'll salute real sharp"}},
{"s7_c04_bursts_then_one_025","any",3,"reg=raider,prison|hour=20,4|mood=grim",{1,"Shooting over toward Riverside, three bursts, then one",2,"Army shoots in bursts",3,"Crews empty everything they got, that was bursts",1,"And the one at the end?",2,"The one at the end is somebody making sure"}},
{"s7_c04_supply_drop_bait_026","any",3,"reg=raider|day=8,200|mood=fear|world=vehicle",{1,"Helicopter dropped pallets in the field behind the school, water, rations, blankets",2,"That's for the families",1,"Families got to walk half a mile of open field to get it - we got a truck",3,"And the Army's got a helicopter that'll come back to see who shows up with a truck",2,"Bait",1,"Maybe bait - maybe blankets"}},
{"s7_c04_did_cody_027","any",2,"reg=raider,prison|tmp=predator|day=5,200|mood=grim|world=vehicle",{1,"I did Cody, out behind the pump house",2,"He ask you to?",1,"Didn't have to ask, looked right at me and then looked at the rifle",2,"Alright",1,"His boots are by the tailgate, somebody's gonna need boots"}},
{"s7_c04_pawn_shop_future_028","any",3,"reg=raider|tmp=predator|mood=funny",{1,"When this is over I'm opening a pawn shop, already got the inventory",2,"Over? When's over?",1,"When the Army leaves and folks have money again",3,"You'll be selling people their own stuff back",1,"At a fair price, with a ninety-day warranty"}},
{"s7_c04_lighter_hammer_029","any",3,"reg=raider,prison|hour=23,4|mood=fear",{1,"Who cocked a hammer just now?",2,"Nobody",1,"I heard a hammer",3,"That was my lighter",1,"Light it, then - go on - let me see the lighter"}},
{"s7_c04_ged_teacher_030","any",3,"reg=prison|day=3,200|mood=sad|world=vehicle",{1,"That's Miss Hensley - GED teacher - Tuesdays and Thursdays",2,"We robbing her or not?",1,"She taught me fractions, I got my certificate in her class - she made a cake",3,"So we're robbing her",1,"You're robbing her, I'm going to go sit in the truck"}},
{"s7_c04_september_coming_031","any",3,"reg=raider|tmp=predator|day=40,200|hour=19,23|mood=grim|world=water,road",{1,"Nights are cooling off - September's coming",2,"So we need blankets",3,"We need a house with a woodstove, and whoever's in it gone",1,"Farmhouse off the creek road has a woodstove - and dogs",2,"Dogs don't live forever"}},
{"s7_c04_mutter_lights_out_032","any",1,"reg=prison|hour=22,2|mood=sad",{1,"Lights out, gentlemen, every night at eleven - Officer Dunn said it like a radio man",1,"Ain't no lights, ain't no Dunn",1,"Lights out, gentlemen"}},
{"s7_c04_mutter_diesel_033","any",1,"reg=raider,prison|day=4,200|mood=fear|world=vehicle,cars",{1,"Diesel engine, down past the church, could be a farm truck",1,"Could be a Humvee, farm trucks don't idle that long",1,"Stay down, count to five hundred, then count it again"}},
{"s7_c04_rotten_freezer_034","any",3,"reg=raider|day=5,200|mood=funny|world=building",{1,"Chest freezer in that basement was full of deer meat - whole deer, wrapped and labeled",2,"Power's been out a week",1,"I know that now, I did not know that when I opened the lid",3,"He opened it with his face right over it - I watched",1,"I can still taste it, and I didn't even eat any"}},
{"s7_c04_water_tower_rope_035","any",3,"reg=raider|day=10,200|mood=fear",{1,"Somebody hung a man off the Muldraugh water tower - sign around his neck",2,"Army?",3,"Army don't do signs - Army does paperwork",1,"Sign said looter",2,"Then it was folks, regular folks did that - that's worse than the Army"}},
{"s7_c04_rival_at_the_kroger_036","any",3,"reg=raider|tmp=predator|mood=angry",{1,"Riverside crew was already inside the grocery when we pulled up - six rifles to our four",2,"So we backed off",1,"So we backed off, their boss tipped his hat, tipped his damn hat at me",3,"That's manners",1,"That's a man telling me he'll see me later"}},
{"s7_c04_mutter_ammo_listen_037","any",1,"reg=raider|tmp=predator|hour=0,5|mood=calm|world=fence",{1,"Twelve - thirteen - fourteen double-aught",1,"Hush, now, something moved by the fence",1,"Possum - fifteen - sixteen"}},
{"s7_c04_shooting_dogs_038","any",3,"reg=raider,prison|day=5,200|mood=fear|world=road",{1,"Army's shooting dogs on the Brandenburg road - every dog",2,"Why dogs?",1,"Don't know, maybe dogs carry it, maybe dogs bark",3,"Or maybe it's practice for folks",2,"Shut up, Dukes"}},
{"s7_c04_bulldozer_road_039","any",3,"reg=raider,prison|day=3,200|mood=angry|world=vehicle,cars,road",{1,"Army piled cars across the Rosewood road with a bulldozer - our car's in the pile",2,"Which car?",1,"The Monte Carlo, third from the top - upside down",3,"We stole that car",1,"And now the United States Army stole it, there's no justice left in this country"}},
{"s7_c04_wont_look_at_him_040","any",3,"reg=raider|tmp=predator,seasoned|mood=grim",{1,"Why won't Junior look at me?",2,"'Cause of the man on Tuesday",1,"The man on Tuesday pulled a knife",3,"Pulled a butter knife - Junior was standing right there",1,"It was still a knife",2,"Tell that to Junior - oh, wait, he ain't looking at you"}},
{"s7_c04_cot_by_the_door_041","any",2,"reg=prison|tmp=predator|hour=21,3|mood=fear|world=door",{1,"Why you moving your cot by the door?",2,"Reno looked at me funny at supper",1,"Reno looks at everybody funny",2,"He looked at me twice, and he smiled the second time",1,"Scoot over, I'm moving mine by the door too"}},
{"s7_c04_mutter_boss_rules_042","any",1,"reg=raider|role=raider_boss|mood=angry",{1,"Every one of 'em thinks I don't see the pocket stuff - I see the pocket stuff",1,"Let 'em have their pockets, a man with pockets thinks he's getting away with something",1,"A man who thinks he's getting away with something don't run off"}},
{"s7_c04_crew_turned_in_043","any",3,"reg=raider|day=8,200|mood=fear|world=water",{1,"Heard the Irvington crew walked up to the Army line and turned in the Brandenburg crew - names, camps, everything",2,"For what?",1,"A ride out, across the river",3,"Anybody know our camp?",2,"Everybody we ever robbed knows our camp, they're the ones that got robbed there"}},
{"s7_c04_same_boots_two_days_044","any",2,"reg=raider,prison|day=12,200|mood=warm",{1,"Who left the dry socks on my boots?",2,"Nobody",1,"Nobody - wool ones, rolled up the way my mamaw rolled 'em",2,"Nobody in this crew does nice things, Skeeter - put 'em on before somebody sees"}},
{"s7_c04_teach_kid_shotgun_045","any",3,"reg=raider|tmp=predator|mood=grim",{1,"Remember Dale wanting that boy taught to use a shotgun?",2,"He was twelve",1,"Dale said twelve was a pair of hands",3,"I wanted the boy learning how to stay out of a fight",1,"Dale wouldn't have called that your decision",3,"Then Dale could have found somebody else to teach him"}},
{"s7_c04_pardon_for_crews_046","any",2,"reg=raider,prison|day=10,200|mood=calm",{1,"When the TV comes back on, somebody's gonna make a list of who did what",2,"They'll need a lot of paper",1,"I'm just saying, some of us need to be real far from Kentucky when the TV comes back on"}},
{"s7_c04_found_fishing_hole_047","any",3,"reg=raider|day=10,200|hour=6,11|mood=warm",{1,"Caught four bluegill off the dock this morning, nobody else up yet",2,"Four - that's supper",1,"Sat there two hours and didn't rob nobody, didn't think about it once",3,"Don't get soft, clean the fish"}},
{"s7_c04_prison_fence_view_048","any",3,"reg=prison|day=10,200|mood=grim|world=fence",{1,"Went up on the ridge, you can see the prison yard from there",2,"And?",1,"The yard's full, hundreds of 'em, walking the fence line, round and round",3,"Doing laps",1,"Doing time"}},
{"s7_c04_quiet_camp_mutter_049","any",1,"reg=raider|tmp=predator|day=20,200|hour=1,5|mood=grim",{1,"Eleven of us that first Friday - seven now",1,"Army got two, the dead got one - we got one ourselves",1,"It's the one we got I keep thinking on"}},
{"s7_c04_hands_behind_head_050","any",3,"reg=prison|tmp=predator|day=2,60|mood=funny",{1,"Robbed a man at the bait shop and he put his hands behind his head and got down on his knees",2,"Without being told?",1,"Without being told, crossed his ankles, too",3,"He's been locked up",1,"That's what I said, he said La Grange, eighty-four to eighty-nine - we ended up giving him a beer"}},
{"s7_c04_names_on_the_tailgate_051","any",3,"reg=raider,prison|day=14,200|hour=19,23|mood=sad|world=vehicle",{1,"Somebody's been scratching names into the tailgate, with a nail",2,"Ours?",1,"Buck - Wendell - Cody - Kenny",3,"That's me, I didn't want 'em rattling around loose",2,"Leave room on there"}},
{"s7_c04_last_run_of_the_day_052","any",4,"reg=raider|tmp=predator|hour=15,19|mood=calm|world=water,generator",{1,"One more house before dark - who's got legs left?",2,"Not me, I carried the generator",3,"Not me, I got the runs from that creek water",4,"I'll go",1,"You always go, Deacon - why do you always go?",4,"'Cause if I go, I pick the house"}},
{"s7_haul_minivan_walkman_001","any",3,"reg=raider|tmp=predator|mood=grim",{1,"Minivan's clean, two cases of water, a bag of charcoal, and a Walkman with a tape still in it",2,"Dibs on the Walkman",3,"That was the kid's, he had both arms wrapped around it the whole time",2,"And now he don't - dibs",3,"Batteries are about dead anyhow"}},
{"s7_haul_shells_tailgate_002","any",2,"reg=raider|tmp=predator|mood=angry|world=vehicle",{1,"Forty-one shells on the tailgate, boss takes half off the top - that's twenty and a half",2,"He'll round up, he always rounds up",1,"So I'm out here risking my neck for ten shotgun shells and a can of peas",2,"Eleven if you count the one in your boot, which he will"}},
{"s7_haul_ring_soap_003","any",3,"reg=raider|tmp=predator,seasoned|mood=grim|world=vehicle",{1,"Old man's ring wouldn't come off, finger swelled right up on him",2,"Dish soap, I told you, dish soap - slides off like butter",1,"He kept saying forty-two years, forty-two years, like I asked",3,"I'm gonna go check on the truck",2,"Truck's fine - sit down"}},
{"s7_haul_beets_camper_004","any",2,"reg=raider|tmp=predator|mood=funny|world=building",{1,"That camper out at Fallas Lake was packed floor to ceiling",2,"With what?",1,"Beets - canned beets - forty cans - who stocks up on beets for the end of the world?",2,"A man who knew nobody'd ever rob him twice"}},
{"s7_haul_vcr_habit_005","any",2,"reg=raider,prison|tmp=predator|mood=funny",{1,"Why is there a VCR in the back of my truck?",2,"Habit, you see a VCR, you grab the VCR",1,"There's no power in the whole county, Lonnie",2,"Still worth something - somewhere - to somebody",1,"Name one person",2,"Me, apparently"}},
{"s7_haul_checkbook_006","any",2,"reg=raider,prison|tmp=predator|mood=funny|world=vehicle",{1,"Kept that fella's checkbook, name and address printed right on every page",2,"What for?",1,"Gonna write myself one for a million dollars, memo line says thanks for the truck",2,"Bank's closed, genius",1,"Then it can't bounce till they open"}},
{"s7_haul_insulin_007","any",3,"reg=raider|tmp=predator,seasoned|mood=grim|world=building",{1,"Four boxes of insulin out of that brick house, fridge was dead but the kitchen stayed cool",2,"The Irvington boys pay good for that stuff",3,"Lady was diabetic, that's why it was in her fridge",2,"Then she should've hid it somewhere else",3,"Where? Where else does a person keep insulin?",1,"Pack it in the cooler, both of you shut up"}},
{"s7_haul_coffee_can_cash_008","any",3,"reg=raider|tmp=predator|hour=19,3|mood=funny|world=building",{1,"Once found three thousand two hundred dollars in a coffee can. Counted it twice",2,"What were you going to buy? A Buick? From who?",3,"I suggested using a twenty as kindling",1,"I told you not to burn my money",3,"You called it yours. Somebody else had hidden it there",1,"Maybe from his own wife, for ten years. Never got to ask him"}},
{"s7_haul_pills_count_009","any",2,"reg=raider,prison|tmp=predator|mood=angry",{1,"There was sixty pills in that bottle when we walked out of the pharmacy",2,"Then there's sixty",1,"There's fifty-one, I can count, Dwayne",2,"Count again, heat makes 'em shrink",1,"Open your mouth"}},
{"s7_haul_timeshare_010","any",3,"reg=raider|tmp=predator,seasoned|mood=funny",{1,"A guy once offered us a timeshare in Gatlinburg. Two weeks every October",2,"Did you take it?",1,"I said I was thinking about it. Leaves are pretty in October",3,"He was crying all over the paper, you can't even read the dates",1,"I said I'd go whenever I wanted. Called it flexible booking. Didn't make him laugh"}},
{"s7_haul_collection_plate_011","any",3,"reg=raider|tmp=predator,seasoned|mood=funny",{1,"Preacher had the Sunday collection in a bank bag, two hundred and six dollars and a button",2,"Somebody put a button in the plate?",3,"I don't like robbing a preacher, my mamaw would come up out of the ground",2,"Lot of folks coming up out of the ground lately - she'll have to take a number",3,"That ain't funny",2,"The button's funny, though"}},
{"s7_haul_scoped_rifle_012","any",3,"reg=raider|tmp=predator|mood=angry",{1,"Rifle with the scope goes to whoever can actually hit something with it",2,"That's me",3,"You shot at a stop sign Sunday and missed, a stop sign",2,"Sign moved",1,"It goes to Hollis - Hollis, quit grinning or I'll change my mind"}},
{"s7_haul_hominy_mutter_013","any",1,"reg=raider,prison|mood=funny|world=stairs",{1,"Fourteen beans - three corn, two peaches in heavy syrup",1,"One hominy - what in God's name is a person supposed to do with hominy?",1,"Peaches go up the ladder, hominy comes down to me, every single time"}},
{"s7_haul_spitter_014","any",2,"reg=raider|tmp=predator|mood=angry|world=building,rooftop,rain",{1,"Woman in the green house spit right in Tully's face - square in the eye",2,"And he let her walk",1,"He laughed, then everybody laughed - and honestly, that was some distance on that spit",2,"Boss hears you let a spitter walk, it won't be impressive - it'll be you on the roof all night in the rain"}},
{"s7_haul_boots_size_015","any",2,"reg=raider,prison|mood=funny",{1,"Took the boots off that deputy - real leather - hardly scuffed",2,"What size?",1,"Nine",2,"You wear an eleven",1,"I'm aware of what I wear, I'm breaking 'em in",2,"You're breaking your toes in"}},
{"s7_haul_polaroid_kids_016","any",2,"reg=raider|tmp=predator,seasoned|mood=sad",{1,"His wallet had two dollars, a fishing license, and a Polaroid of three kids on a trampoline",2,"Toss it",1,"Yeah",2,"I said toss it - why's it still in your hand?",1,"I'm tossing it - God, give a man a second"}},
{"s7_haul_ammo_ledger_017","any",2,"reg=raider|day=5,200|mood=calm",{1,"Write it down, nine millimeter, two boxes, thirty-eight special, loose, twenty-three rounds",2,"Twenty-three - got it - what's this brass one?",1,"No idea, came out of a nightstand in {town}, doesn't fit a single gun we own",2,"Trade goods, then, bottom shelf with the fishing sinkers"}},
{"s7_haul_warm_beer_018","any",3,"reg=raider,prison|hour=10,19|mood=funny",{1,"Liquor store on 31W, front glass is gone, but the back cooler had two cases nobody touched",2,"Cold?",1,"Warm as bathwater",3,"Warm beer is still beer, don't be ungrateful",2,"I'm not ungrateful - I'm hot, there's a difference"}},
{"s7_haul_pawn_guitars_019","any",3,"reg=raider|hour=16,5|mood=funny|world=building",{1,"Pawn shop in Muldraugh had eleven guitars hanging on the wall - eleven",2,"Anybody here play?",3,"I know the first half of one song",1,"Nobody plays, so we left 'em",3,"I took one, a little one",2,"I hear half a song tonight, that guitar goes in the fire"}},
{"s7_haul_bb_gun_020","any",3,"reg=raider|tmp=predator,seasoned|mood=grim|world=door",{1,"Kid comes out the side door with a BB gun, pumping it - ten pumps at least",2,"Stung like a hornet too - look at my neck",1,"Hahaha! Got shot by a sixth grader!",3,"What'd you do to him?",2,"Took the BB gun",3,"That's all?",2,"What do you want me to say? That's all"}},
{"s7_haul_cigarette_split_021","any",2,"reg=raider,prison|tmp=predator|mood=angry",{1,"Carton splits five ways, two packs apiece",2,"You don't even smoke",1,"Don't have to smoke, a pack of smokes gets you a box of shells in Brandenburg right now",2,"Fine, you're not getting menthols, menthols are mine",1,"Nobody wants your menthols, nobody in history has ever wanted menthols"}},
{"s7_haul_lottery_ticket_022","any",2,"reg=raider,prison|tmp=predator|day=2,90|mood=grim",{1,"Wallet had a lottery ticket in it, drawing was supposed to be Saturday",2,"Check the numbers?",1,"Against what? Nobody drew nothing Saturday",2,"So he could be a millionaire",1,"He could be, he's also face down in the ditch by the Dixie Highway"}},
}
